@Component("placement-handler")
@ProcessingGroup("placement-processing-group")
public class PlacementEventHandler {
	
	// core constructor
	PlacementEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePlacementEvent
     */
    @EventHandler
    public void handle( CreatePlacementEvent event) {
        entityManager.persist(new Placement(event.getPlacementId(), event.getName(), event.getFlight(), event.getGoalImpressions(), event.getLineItem(), event.getAdSlot(), event.getDeal()));
    }

    /*
     * @param	event UpdatePlacementEvent
     */
    @EventHandler
    public Placement handle( UpdatePlacementEvent event) {
    	entityManager.merge(new Placement(event.getPlacementId(), event.getName(), event.getFlight(), event.getGoalImpressions(), event.getLineItem(), event.getAdSlot(), event.getDeal()));
    }
    
    /*
     * @param	event DeletePlacementEvent
     */
    @EventHandler
    public void on( DeletePlacementEvent event) {
    	Placement entity = new Placement();
   
    	// ------------------------------------------
    	// apply the PlacementId
    	// ------------------------------------------
    	entity.setPlacementId( event.getPlacementId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PlacementRepository placementEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PlacementEventHandler.class.getName());

}
